export function bundledCatalogImageModule(imagePath: string): number | null {
  if (!isBundledCatalogImagePath(imagePath)) return null;
  return BUNDLED_CATALOG_IMAGE_MODULES[imagePath.slice(BUNDLED_CATALOG_IMAGE_PREFIX.length)] ?? null;
}
